S['NONG2011A'] = [{'k': 'noti', 'ch': 'Mở đầu', 'short': True, 'cap': ('NGÂN HÀNG GIẢM 3.413 NGƯỜI', 'CHỈ SAU 9 THÁNG'), 'cols': ((255, 255, 255), (239, 68, 68)), 'noti': {'gio': '17:40', 'ngay': 'Thứ Năm', 'items': [('Tin tức', 'Ngân hàng', '28 ngân hàng giảm 3.413 nhân sự sau 9 tháng', (255, 196, 0)), ('Chồng', 'Tin nhắn', 'Em xem tin chưa? Chỗ em có cắt không?', (56, 189, 248))]}, 'say': 'Năm giờ bốn mươi chiều qua, chị Hằng vừa tắt máy tính ở phòng hồ sơ tín dụng của một ngân hàng tại Hà Nội thì điện thoại hiện một tin. Theo báo Người Quan Sát, hai mươi tám ngân hàng đã giảm ba nghìn bốn trăm mười ba nhân sự chỉ sau chín tháng năm nay. Bài báo cũng dẫn lời lãnh đạo một số ngân hàng: những việc mang tính lặp lại đang dần được tự động hoá. Ngay sau đó là tin nhắn của chồng chị: em xem tin chưa, chỗ em có cắt không?'}, {'k': 'bignum', 'anh': 'ov:Hanoi skyline night||Hanoi skyline night', 'cap': ('MỘT NGÂN HÀNG', 'GIẢM HƠN 25% NHÂN SỰ'), 'cols': ((255, 255, 255), (239, 68, 68)), 'value': 4263, 'fmt': '{:,.0f}', 'unit': ' người', 'top': 'SACOMBANK GIẢM NHÂN SỰ SAU 9 THÁNG', 'sub': 'Còn 12.553 người, giảm 25,35% so với cuối năm 2025', 'col': (239, 68, 68), 'say': 'Con số làm chị Hằng giật mình nhất là bốn nghìn hai trăm sáu mươi ba. Đó là số người Sacombank giảm trong chín tháng, hơn hai mươi lăm phần trăm đội ngũ. Chị làm nhập hồ sơ đã chín năm. Việc của chị có nằm trong nhóm bị thay trước không? Và đằng sau con số ba nghìn bốn trăm người, thật ra đang có chuyện gì?'}, {'k': 'giay', 'ch': 'Chương 1 – Con số 3.413 người', 'cap': ('NHÂN SỰ 28 NGÂN HÀNG', 'ĐẾN NGÀY 30/9/2026'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'giay': {'tieu_de': 'NHÂN SỰ 28 NGÂN HÀNG', 'so': 'Theo Người Quan Sát 19/11/2026, từ báo cáo tài chính', 'dau': 'ĐÃ ĐỌC', 'dieu': [('Tổng nhân sự 30/9: 278.157 người.', 'GIẢM 3.413'), ('Số ngân hàng giảm người: 14.', 'GIẢM'), ('Số ngân hàng tăng người: 13.', 'TĂNG'), ('Giữ nguyên: 1 ngân hàng.', 'ĐỨNG YÊN')]}, 'say': 'Tối đó chị Hằng đọc kỹ bài báo. Đến ngày ba mươi tháng chín, hai mươi tám ngân hàng còn hơn hai trăm bảy mươi tám nghìn người, giảm ba nghìn bốn trăm mười ba người so với cuối năm ngoái. Mức giảm chỉ hơn một phần trăm. Nhưng dòng tiếp theo mới đáng chú ý. Chỉ có mười bốn ngân hàng giảm người. Mười ba ngân hàng khác lại tăng người, và một ngân hàng giữ nguyên.'}, {'k': 'cards', 'anh': 'ov:Bitexco Financial Tower||Bitexco Financial Tower', 'cap': ('NƠI GIẢM', 'NƠI TĂNG NGƯỜI'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'cards': [('4.263', 'Sacombank giảm 25,35%', 'GIẢM NHIỀU NHẤT'), ('783', 'Eximbank giảm 12,75%', 'GIẢM'), ('1.956', 'VPBank tăng 6,8%', 'TĂNG NHIỀU NHẤT')], 'say': 'Bên giảm, sau Sacombank là Eximbank, giảm bảy trăm tám mươi ba người. Ba ngân hàng có vốn nhà nước chi phối là BIDV, VietinBank và Vietcombank cũng giảm nhẹ. Bên tăng, VPBank tăng gần hai nghìn người, thành ngân hàng duy nhất vượt ba mươi nghìn nhân sự. HDBank và Techcombank cũng tuyển thêm.'}, {'k': 'chat', 'cap': ('"VẬY LÀ NGÂN HÀNG', 'ĐANG CẮT NGƯỜI Ồ ẠT?"'), 'cols': ((255, 255, 255), (239, 68, 68)), 'moc': True, 'chat': {'ten': 'Anh Nam', 'tv': 'Đang hoạt động', 'gio': '21:10', 'mau': (56, 189, 248), 'msgs': [('Anh Nam', 'Vậy là ngân hàng đang cắt người ồ ạt à em?'), ('me', 'Em cộng thử rồi, không hẳn vậy'), ('me', 'Bỏ một ngân hàng ra là 27 nhà còn lại tăng người')]}, 'say': 'Chồng chị, anh Nam, nhắn hỏi: vậy là ngân hàng đang cắt người ồ ạt à em? Chị Hằng ngồi cộng thử từng dòng, rồi trả lời rằng không hẳn vậy. Bên giảm thì nhiều, nhưng bên tăng người cũng không hề ít.'}, {'k': 'bignum', 'anh': 'ov:Ho Chi Minh City skyline night||Ho Chi Minh City skyline night', 'cap': ('BỎ RIÊNG SACOMBANK RA', '27 NGÂN HÀNG CÒN LẠI TĂNG 850'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'value': 850, 'fmt': '{:,.0f}', 'unit': ' người', 'top': '27 NGÂN HÀNG CÒN LẠI: TĂNG THÊM', 'sub': 'Em tự tính: giảm 3.413, cộng lại 4.263 của Sacombank', 'col': (34, 197, 94), 'say': 'Và đây là cú lật đầu tiên. Một mình Sacombank giảm bốn nghìn hai trăm sáu mươi ba người, nhiều hơn cả mức giảm chung của hai mươi tám ngân hàng. Bỏ riêng ngân hàng này ra, hai mươi bảy ngân hàng còn lại không hề giảm người, mà còn tăng thêm khoảng tám trăm năm mươi người. Theo CafeF, Sacombank đang tinh gọn bộ máy, chuyển sang quản lý theo chín khối nghiệp vụ và bỏ bớt tầng nấc trung gian.'}, {'k': 'noti', 'ch': 'Chương 2 – Việc nào bị thay trước?', 'cap': ('VIỆC NHẬP LIỆU, HỒ SƠ', 'ĐANG BỊ MÁY THAY DẦN'), 'cols': ((255, 255, 255), (239, 68, 68)), 'moc': True, 'noti': {'gio': '21:30', 'ngay': 'Thứ Năm', 'items': [('Tin tức', 'Ngân hàng', 'TPBank cắt nhân sự gián tiếp ở việc lặp lại', (239, 68, 68)), ('Tin tức', 'Ngân hàng', 'Năm trước bổ sung gần 200 nhân sự công nghệ, dữ liệu', (34, 197, 94))]}, 'say': 'Nhưng phần sau của bài báo mới làm chị Hằng lo thật. Tổng giám đốc TPBank cho biết ngân hàng đã cắt giảm nhân sự gián tiếp ở các vị trí mang tính lặp lại, như nhập liệu hay xử lý hồ sơ thủ công. Nhiều quy trình trước đây mất hàng giờ, nay chỉ còn vài phút nhờ tự động hoá. Cùng lúc, ngân hàng tăng người bán hàng trực tiếp, và năm trước đã bổ sung gần hai trăm nhân sự công nghệ, dữ liệu.'}, {'k': 'giay', 'short': True, 'cap': ('TUẦN 40 GIỜ CỦA CHỊ HẰNG', '26 GIỜ LÀ VIỆC LẶP LẠI'), 'cols': ((255, 255, 255), (239, 68, 68)), 'moc': True, 'giay': {'tieu_de': 'MỘT TUẦN LÀM VIỆC CỦA CHỊ HẰNG', 'so': 'Em giả định để minh hoạ', 'dau': 'GIẢ ĐỊNH', 'dieu': [('Nhập hồ sơ vay vào hệ thống: 18 giờ.', 'LẶP LẠI'), ('Đối chiếu giấy tờ theo mẫu: 8 giờ.', 'LẶP LẠI'), ('Gọi khách bổ sung hồ sơ: 8 giờ.', 'GẶP NGƯỜI'), ('Họp và việc khác: 6 giờ.', 'KHÁC')]}, 'say': 'Chị Hằng lấy giấy ra ghi lại một tuần làm việc của mình. Em giả định một tuần bốn mươi giờ. Mười tám giờ nhập hồ sơ vay vào hệ thống, tám giờ đối chiếu giấy tờ theo mẫu. Tám giờ gọi khách hàng bổ sung hồ sơ, sáu giờ họp và việc khác. Cộng lại, hai mươi sáu trên bốn mươi giờ, tức sáu mươi lăm phần trăm thời gian của chị là việc lặp lại.'}, {'k': 'cards', 'anh': 'ov:Bitexco Financial Tower||Bitexco Financial Tower', 'cap': ('LÃNH ĐẠO NGÂN HÀNG', 'NÓI GÌ VỀ MÁY VÀ NGƯỜI?'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'cards': [('10 còn 3', 'Nhóm dự án, kèm chục tác nhân AI', 'TRONG TƯƠNG LAI'), ('25–30%', 'Năng suất lập trình nhờ AI', 'ĐÃ ĐẠT'), ('90%', 'Nhân viên dùng AI thường xuyên', 'MỤC TIÊU 2026')], 'say': 'Lãnh đạo các ngân hàng khác nói gì? Phó tổng giám đốc VietinBank nêu khả năng một nhóm dự án khoảng mười người, trong tương lai có thể chỉ còn khoảng ba người, cùng một chục tác nhân trí tuệ nhân tạo hỗ trợ. Ở Techcombank, phó tổng giám đốc cho biết công cụ hỗ trợ lập trình đã giúp năng suất tăng từ hai mươi lăm đến ba mươi phần trăm. Techcombank đặt mục tiêu chín mươi phần trăm nhân viên dùng trí tuệ nhân tạo thường xuyên trong năm nay.'}, {'k': 'chat', 'cap': ('"KHÔNG PHẢI LO BỊ CẮT', 'MÀ ĐƯỢC ĐÀO TẠO LẠI"'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'chat': {'ten': 'Chị Lan', 'tv': 'Trưởng phòng cũ', 'gio': '22:00', 'mau': (255, 196, 0), 'msgs': [('Chị Lan', 'Techcombank nói nhân viên không phải lo bị cắt vì máy'), ('Chị Lan', 'Mà sẽ được đào tạo lại, làm nhiều việc hơn'), ('me', 'Vậy người không chịu học thì sao chị?')]}, 'say': 'Chị Hằng nhắn hỏi chị Lan, trưởng phòng cũ của mình. Chị Lan gửi lại một đoạn trong bài. Phó tổng giám đốc Techcombank nói người lao động không phải lo bị cắt giảm vì máy. Công nghệ sẽ làm phát sinh nghiệp vụ mới, và nhân viên sẽ được đào tạo lại. Chị Hằng hỏi lại: vậy người không chịu học thì sao chị? Chị Lan không trả lời ngay.'}, {'k': 'bignum', 'anh': 'ov:Ho Chi Minh City skyline night||Ho Chi Minh City skyline night', 'short': True, 'cap': ('VIETCOMBANK CHI CHO MỖI NGƯỜI', '65,6 TRIỆU MỖI THÁNG'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'value': 65.6, 'fmt': '{:,.1f}', 'unit': ' triệu', 'top': 'CHI PHÍ BÌNH QUÂN MỖI NHÂN VIÊN VIETCOMBANK', 'sub': 'Mỗi tháng, 9 tháng 2026, tăng 30,3% cùng kỳ (CafeF 8/11/2026)', 'col': (255, 196, 0), 'say': 'Rồi cú lật thứ hai. Giảm người không có nghĩa là ngân hàng chi ít tiền hơn cho con người. Theo CafeF, ở Vietcombank, chi phí nhân viên bình quân, tính cả lương thưởng, bảo hiểm và phúc lợi, là hơn sáu mươi lăm triệu đồng mỗi người mỗi tháng trong chín tháng đầu năm. Con số này tăng ba mươi phẩy ba phần trăm so với cùng kỳ. Đây là tiền ngân hàng bỏ ra, không phải lương thực nhận. Còn Sacombank, nơi giảm người nhiều nhất, nói muốn đưa thu nhập nhân viên lên đứng đầu ngành.'}, {'k': 'cards', 'anh': 'ov:Bitexco Financial Tower||Bitexco Financial Tower', 'cap': ('AI CHỊU SỨC ÉP', 'KHI NGÂN HÀNG TINH GỌN'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'cards': [('46,1% còn 32,6%', 'Chi phí trên thu nhập Sacombank', 'VẬN HÀNH GỌN HƠN'), ('30,3%', 'Chi phí mỗi người Vietcombank', 'TĂNG SO CÙNG KỲ'), ('65%', 'Việc lặp lại (giả định)', 'CHỊU SỨC ÉP NHẤT')], 'say': 'Vậy ai chịu sức ép? Theo CafeF, ở Sacombank, tỷ lệ chi phí trên thu nhập đã giảm từ bốn mươi sáu phẩy một phần trăm xuống ba mươi hai phẩy sáu phần trăm. Mỗi đồng thu vào, ngân hàng tốn ít hơn để vận hành. Còn theo chính lời lãnh đạo TPBank, vị trí bị cắt trước là những vị trí gián tiếp, làm việc lặp lại. Tức là những người như chị Hằng.'}, {'k': 'call', 'ch': 'Chương 3 – Lần trước là năm 2023', 'cap': ('"NĂM 2023 ANH CŨNG', 'TƯỞNG CẢ NGÀNH CẮT NGƯỜI"'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'call': {'ten': 'Anh Tùng', 'phu': 'Bạn học cũ', 'mau': (255, 196, 0), 'loi': ['Năm 2023 công ty anh cắt hàng nghìn người', 'Mà ngân hàng khác vẫn tuyển']}, 'say': 'Tối qua chị Hằng gọi cho anh Tùng, bạn học cũ. Năm hai nghìn không trăm hai mươi ba, anh làm ở một công ty tài chính và nằm trong đợt bị cắt giảm. Anh kể: lúc đó anh cũng tưởng cả ngành đang cắt người. Mà hoá ra cùng năm đó, nhiều ngân hàng khác vẫn tuyển thêm. Anh mất nửa năm mới tìm được việc mới, ở một chỗ cần người biết gặp khách.'}, {'k': 'giay', 'cap': ('NĂM 2023', 'NHỮNG CON SỐ CỦA LẦN TRƯỚC'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'giay': {'tieu_de': 'NHỮNG CON SỐ CỦA LẦN TRƯỚC', 'so': 'Theo VietnamFinance 19/12/2023, số đến 30/9/2023', 'dau': 'SO SÁNH', 'dieu': [('VPBank hợp nhất giảm 4.400 người.', 'CÔNG TY CON'), ('LPBank giảm 1.870 người.', 'GIẢM'), ('VIB tăng 1.614 người.', 'TĂNG'), ('Vietcombank tăng 911 người.', 'TĂNG')]}, 'say': 'Những con số của lần trước. Theo VietnamFinance, chín tháng đầu năm hai nghìn không trăm hai mươi ba, VPBank tính cả công ty thành viên giảm bốn nghìn bốn trăm người, chủ yếu ở công ty thành viên. Cùng lúc, VIB và Vietcombank vẫn tuyển thêm. Theo bài báo khi đó, lý do giảm người là tín dụng tăng chậm, nợ xấu tăng nhanh, bán bảo hiểm qua ngân hàng bị siết.'}, {'k': 'checklist', 'anh': 'ov:Hanoi skyline night||Hanoi skyline night', 'cap': ('GIỐNG 2, KHÁC 2', 'SO VỚI NĂM 2023'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'items': [('Giống: nơi giảm, nơi tăng', (255, 196, 0)), ('Giống: số chung che số từng nhà', (255, 196, 0)), ('Khác: 2023 vì nợ xấu', (239, 68, 68)), ('Khác: nay có nơi nói máy thay', (239, 68, 68))], 'say': 'So với năm hai nghìn không trăm hai mươi ba, có hai điểm giống và hai điểm khác. Giống ở chỗ nơi giảm, nơi tăng cùng lúc. Và con số chung che mất chuyện từng nhà: năm nay riêng Sacombank đã giảm nhiều hơn mức giảm chung, khi tái cấu trúc bộ máy. Khác ở chỗ lần trước, các ngân hàng giảm người vì kinh doanh khó. Lần này, có ngân hàng nói thẳng việc lặp lại đang được máy làm thay. Vị trí như vậy, chờ kinh doanh khá lên chưa chắc đã có lại.'}, {'k': 'cards', 'ch': 'Chương 4 – Ba con đường của chị Hằng', 'anh': 'ov:Hanoi apartment buildings||Hanoi apartment buildings', 'cap': ('3 CON ĐƯỜNG', 'CHO NGƯỜI LÀM VIỆC LẶP LẠI'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'cards': [('Chờ', 'Giữ nguyên cách làm', 'RỦI RO NHẤT'), ('Học công cụ', 'Làm việc cũ nhanh hơn', 'GIỮ CHỖ ĐỨNG'), ('Chuyển việc', 'Gặp khách, dữ liệu', 'THU NHẬP BIẾN ĐỘNG')], 'say': 'Chị Hằng thấy có ba con đường. Một, giữ nguyên cách làm và chờ. Đường này dễ nhất hôm nay, nhưng rủi ro nhất nếu phòng chị đổi quy trình. Hai, học dùng chính công cụ tự động để làm việc của mình nhanh hơn, trở thành người kiểm tra ca khó. Ba, xin chuyển sang gặp khách hàng hoặc dữ liệu, mảng mà TPBank đang tăng người. Nhưng thu nhập bán hàng đi theo chỉ tiêu, có tháng cao tháng thấp.'}, {'k': 'chat', 'cap': ('"MỖI TỐI EM HỌC 1 GIỜ', 'TRONG 3 THÁNG"'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'chat': {'ten': 'Anh Nam', 'tv': 'Đang hoạt động', 'gio': '07:30', 'mau': (56, 189, 248), 'msgs': [('me', 'Em sẽ học công cụ tự động mỗi tối một giờ'), ('me', 'Ba tháng nữa em xin làm khâu kiểm tra hồ sơ khó'), ('Anh Nam', 'Ừ, anh trông con buổi tối cho em học')]}, 'say': 'Sáng nay chị Hằng nhắn chồng kế hoạch. Chị sẽ học công cụ tự động mỗi tối một giờ, ba tháng nữa xin chuyển sang khâu kiểm tra những hồ sơ khó, việc máy chưa tự làm được. Anh Nam trả lời rằng anh sẽ trông con buổi tối cho chị học. Đó là lựa chọn riêng của gia đình chị.'}, {'k': 'checklist', 'ch': 'Chương 5 – Phép thử cho công việc', 'anh': 'ov:Ho Chi Minh City skyline night||Ho Chi Minh City skyline night', 'cap': ('PHÉP THỬ', 'BAO NHIÊU % LÀ VIỆC LẶP LẠI?'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'items': [('Dưới 30%: khá vững', (34, 197, 94)), ('Từ 30 đến 60%: nên học thêm', (255, 196, 0)), ('Trên 60%: nên đặt kế hoạch', (239, 68, 68))], 'say': 'Em gợi ý một phép thử tự soi, dù anh chị làm ngân hàng hay nghề khác. Ghi lại một tuần làm việc, rồi tính bao nhiêu phần trăm thời gian là việc lặp lại theo mẫu: nhập liệu, sao chép, đối chiếu. Dưới ba mươi phần trăm, công việc khá vững. Từ ba mươi đến sáu mươi phần trăm, nên học thêm công cụ. Trên sáu mươi phần trăm, như chị Hằng, là lúc nên tự đặt kế hoạch như chị đã làm. Đây là mốc tự soi, không phải lời khuyên.'}, {'k': 'checklist', 'anh': 'ov:Ho Chi Minh City Metro Line 1||Ho Chi Minh City Metro Line 1', 'cap': ('3 ĐIỀU CẦN THEO DÕI', 'TỪ NAY TỚI ĐẦU NĂM 2027'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'items': [('Nhân sự quý 4 trong báo cáo', (255, 196, 0)), ('Ngân hàng nào tuyển thêm', (255, 196, 0)), ('Việc nào đổi quy trình', (239, 68, 68))], 'say': 'Ba điều đáng theo dõi. Số nhân sự quý bốn, khi các ngân hàng công bố báo cáo tài chính cuối tháng một năm hai nghìn không trăm hai mươi bảy. Ngân hàng nào đang tuyển thêm, và tuyển cho vị trí gì. Và trong chính chỗ làm của mình, việc nào vừa được đổi sang quy trình tự động. Muốn hiểu ngân hàng kiếm tiền và tiêu tiền ra sao, anh chị có thể đọc bài miễn phí trên chứng khoán Huy Nguyễn chấm com.'}, {'k': 'chat', 'ch': 'Kết – Tin nhắn cuối ngày', 'cap': ('"PHÒNG MÌNH CÓ NGƯỜI', 'ĐÃ CHUYỂN SANG THẨM ĐỊNH"'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'chat': {'ten': 'Chị Lan', 'tv': 'Đang hoạt động', 'gio': '08:00', 'mau': (255, 196, 0), 'msgs': [('Chị Lan', 'Năm ngoái phòng mình có Vy chuyển sang thẩm định'), ('Chị Lan', 'Em hỏi Vy đã học gì đi'), ('me', 'Dạ, trưa nay em hẹn Vy cà phê')]}, 'say': 'Tám giờ sáng, chị Lan nhắn lại câu trả lời cho câu hỏi hôm qua. Năm ngoái, phòng chị có Vy, cũng làm nhập liệu, đã chuyển sang khâu thẩm định. Em hỏi Vy đã học gì đi. Chị Hằng trả lời: dạ, trưa nay em hẹn Vy cà phê.'}, {'k': 'end', 'cap': ('TUẦN LÀM VIỆC CỦA ANH CHỊ', 'BAO NHIÊU % LÀ LẶP LẠI?'), 'cols': ((255, 255, 255), (255, 196, 0)), 'say': 'Còn anh chị, một tuần làm việc của mình có khoảng bao nhiêu phần trăm là việc lặp lại? Ghi một con số ở phần bình luận cho em và mọi người nhé.'}]
META = {'NONG2011A': {'kenh': '@chungkhoanhuynguyen', 'seri': 'Tin nóng trong ngày', 'ngay': '2026-11-20', 'gio_goi_y': '19:30', 'gio': '19:30', 'nhac': 'lofi', 'tieu_de': 'Ngân Hàng Giảm 3.413 Nhân Sự Sau 9 Tháng: Một Nơi Giảm 25% – Việc Nào Bị Máy Thay Trước?', 'title': 'Ngân Hàng Giảm 3.413 Nhân Sự Sau 9 Tháng: Một Nơi Giảm 25% – Việc Nào Bị Máy Thay Trước?', 'mo_ta': 'NÓNG: theo Người Quan Sát (19/11/2026), đến 30/9/2026 nhân sự 28 ngân hàng còn 278.157 người, giảm 3.413 người so với cuối 2025. Sacombank giảm 4.263 người (25,35%). Nhưng 13 ngân hàng lại tăng 5.064 người (số thay đổi ròng), và lãnh đạo một số ngân hàng nói rõ: việc lặp lại như nhập liệu, xử lý hồ sơ thủ công đang được máy thay. Ai chịu sức ép, lần trước năm 2023 ra sao, và phép thử cho công việc của anh chị.\n\nNguồn số liệu:\n• Người Quan Sát 19/11/2026 (từ báo cáo tài chính 9 tháng): 28 ngân hàng còn 278.157 người, giảm 3.413 (1,21%); 14 giảm, 13 tăng (tổng tăng 5.064), 1 giữ nguyên; Sacombank 12.553 (−4.263, −25,35%); Eximbank 5.358 (−783); VIB 9.600 (−678); KienlongBank 2.596 (−629); BIDV −504, VietinBank −306, Vietcombank −197; VPBank 30.724 (+1.956, +6,8%); HDBank 19.608 (+1.335); Techcombank 13.296 (+591). Ý kiến lãnh đạo TPBank, VietinBank, Techcombank về tự động hoá và AI\n• CafeF 17/11/2026: Sacombank tinh gọn bộ máy, quản lý ngành dọc 9 khối; tỷ lệ chi phí/thu nhập (CIR) 46,1% → 32,6%; mục tiêu đứng đầu thu nhập nhân viên\n• CafeF 8/11/2026: chi phí nhân viên bình quân (gồm lương thưởng, bảo hiểm, phúc lợi – không phải lương thực nhận) 9 tháng 2026 tại Vietcombank 65,6 triệu đồng/người/tháng, +30,3% cùng kỳ\n• VietnamFinance 19/12/2023 (số đến 30/9/2023): VPBank hợp nhất −4.400 (ngân hàng mẹ +48, giảm chủ yếu ở công ty thành viên); LPBank −1.870; VIB +1.614; Vietcombank +911\n• Tự tính (số thay đổi ròng): tổng giảm của 14 ngân hàng = 3.413 + 5.064 = 8.477; bỏ Sacombank: −3.413 + 4.263 = +850 người. Tuần làm việc chị Hằng là GIẢ ĐỊNH: 40 giờ, 26 giờ việc lặp lại = 65%\n\nNgân hàng kiếm tiền ra sao: https://chungkhoanhuynguyen.com/hoc/\nCần trao đổi riêng về kế hoạch tài chính: Zalo 0365.188.286\n\nNhân vật chị Hằng, anh Nam, chị Lan, anh Tùng, Vy là hư cấu; số liệu là thật theo nguồn trên.\nChia sẻ góc nhìn, không phải khuyến nghị.', 'tags': ['ngân hàng cắt giảm nhân sự', 'nhân sự ngân hàng', 'cắt giảm nhân sự', 'AI thay thế việc làm', 'Sacombank', 'thu nhập nhân viên ngân hàng', 'việc làm', 'tự động hoá', 'tin nóng tài chính', 'ngân hàng 2026'], 'bia_hook': ['NGÂN HÀNG GIẢM', '3.413 NGƯỜI'], 'badge': 'NHÂN SỰ NGÂN HÀNG 9T', 'bia_anh': 'Hanoi skyline night||Hanoi skyline night', 'bia_hook_b': ['BỎ 1 NHÀ RA', 'LẠI TĂNG 850'], 'badge_b': 'NHÂN SỰ 27 NGÂN HÀNG', 'bia_hook_c': ['VIỆC LẶP LẠI', 'MẤT TRƯỚC?'], 'badge_c': 'NHẬP LIỆU BỊ THAY DẦN', 'reel_hook': 'NGÂN HÀNG GIẢM 3.413 NGƯỜI|VIỆC NÀO MẤT TRƯỚC???', 'fb_post': 'Ngân hàng giảm 3.413 nhân sự sau 9 tháng 🏦\n\n👉 Một ngân hàng giảm 4.263 người (25%)\n👉 Nhưng 13 ngân hàng khác tăng 5.064 người\n👉 Việc nhập liệu, xử lý hồ sơ thủ công đang bị máy thay dần\n\nTuần làm việc của anh chị bao nhiêu % là việc lặp lại?\n🎬 Xem đầy đủ: {LINK}', 'chuong': ['Mở đầu', 'Chương 1 – Con số 3.413 người', 'Chương 2 – Việc nào bị thay trước?', 'Chương 3 – Lần trước là năm 2023', 'Chương 4 – Ba con đường của chị Hằng', 'Chương 5 – Phép thử cho công việc', 'Kết – Tin nhắn cuối ngày']}}
